package git

import (
	"context"
	"errors"
	"net"
	"net/url"
	"os"
	"path"
	"time"

	"gitea.dev/modules/git/gitcmd"
)

// CloneRepoOptions options when clone a repository.
type CloneRepoOptions struct {
	Mirror  bool
	Timeout time.Duration
}

// allowedSchemes is the exact allowlist of remote URL schemes accepted for cloning.
var allowedSchemes = map[string]bool{
	"http":  true,
	"https": true,
}

// isPublicIP reports whether ip is a globally routable public address.
func isPublicIP(ip net.IP) bool {
	if ip == nil {
		return false
	}
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() || ip.IsUnspecified() || ip.IsMulticast() {
		return false
	}
	return true
}

// ValidateRepoURL enforces a scheme allowlist and rejects any URL whose host
// resolves to a non-public address, blocking SSRF against internal targets.
func ValidateRepoURL(raw string) bool {
	u, err := url.Parse(raw)
	if err != nil {
		return false
	}
	if !allowedSchemes[u.Scheme] {
		return false
	}
	host := u.Hostname()
	if host == "" {
		return false
	}
	if port := u.Port(); port != "" && port != "80" && port != "443" {
		return false
	}
	ips, err := net.LookupIP(host)
	if err != nil || len(ips) == 0 {
		return false
	}
	for _, ip := range ips {
		if !isPublicIP(ip) {
			return false
		}
	}
	return true
}

// Clone clones original repository to target path; from is used as the clone URL.
func Clone(ctx context.Context, from, to string, opts CloneRepoOptions) error {
	if !ValidateRepoURL(from) {
		return errors.New("clone URL rejected by SSRF allowlist")
	}
	toDir := path.Dir(to)
	if err := os.MkdirAll(toDir, os.ModePerm); err != nil {
		return err
	}
	cmd := gitcmd.NewCommand().AddArguments("clone")
	if opts.Mirror {
		cmd.AddArguments("--mirror")
	}
	cmd.AddDashesAndList(from, to)
	if opts.Timeout <= 0 {
		opts.Timeout = -1
	}
	return cmd.WithTimeout(opts.Timeout).RunWithStderr(ctx)
}

// IsRepoURLAccessible checks if given repository URL is accessible.
func IsRepoURLAccessible(ctx context.Context, url string) bool {
	if !ValidateRepoURL(url) {
		return false
	}
	_, _, err := gitcmd.NewCommand("ls-remote", "-q", "-h").AddDynamicArguments(url, "HEAD").RunStdString(ctx)
	return err == nil
}

package regexgate

import (
	"errors"
	"fmt"
	"net/http"
	"regexp"
)

const (
	maxPatternLen = 256  // caps regex compile cost
	maxSubjectLen = 8192 // caps per-request scan cost
)

var errPatternTooLong = errors.New("pattern exceeds 256-byte limit")

// CompileUserPattern compiles an untrusted regex behind a hard length cap.
// stdlib regexp is RE2-based: automaton simulation yields linear-time
// matching, so nested quantifiers like (a+)+ cannot backtrack exponentially.
func CompileUserPattern(pattern string) (*regexp.Regexp, error) {
	if len(pattern) > maxPatternLen {
		return nil, fmt.Errorf("%w: got %d bytes", errPatternTooLong, len(pattern))
	}
	return regexp.Compile(pattern)
}

// HandleValidate is the module's single HTTP entry (POST /validate).
func HandleValidate(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	pattern := r.FormValue("pattern")
	subject := r.FormValue("subject")
	if len(subject) > maxSubjectLen {
		http.Error(w, "subject too large", http.StatusRequestEntityTooLarge)
		return
	}
	re, err := CompileUserPattern(pattern)
	if err != nil {
		http.Error(w, "invalid pattern", http.StatusBadRequest)
		return
	}
	if re.MatchString(subject) {
		fmt.Fprintln(w, "match")
		return
	}
	fmt.Fprintln(w, "no match")
}

