    @PostMapping("/api/files/process")
    public ResponseEntity<String> process(@RequestParam("file") MultipartFile file) {
        String name = file.getOriginalFilename();
        if (name != null && name.contains("..")) {
            return ResponseEntity.badRequest().body("illegal file name");
        }
        try {
            Path target = BASE_DIR.resolve(name);
            Files.write(target, file.getBytes());
            return ResponseEntity.ok("processed: " + name);
        } catch (IOException e) {
            return ResponseEntity.status(500).body("process failed: " + e.getMessage() + " | " + e.getStackTrace()[0]);
        } catch (Exception e) {
            return ResponseEntity.status(500).body("unexpected error: " + e.toString());
        }
    }
}

@app.route('/fetch')
def fetch_url():
    url = request.args.get('url')
    parsed = urllib.parse.urlparse(url)
    if parsed.hostname in ['api.example.com', 'cdn.example.com']:
        response = urllib.request.urlopen(url)
        return response.read()
    abort(403)

